<script setup lang="ts">useHead({title:'ورود'});const{api,token}=useShopApi(),route=useRoute();const step=ref('mobile'),mobile=ref('09120000000'),code=ref('12345'),loading=ref(false),error=ref('');async function send(){loading.value=true;try{await api('/auth/otp/request',{method:'POST',body:{mobile:mobile.value}});step.value='code'}catch(e:any){error.value=e?.data?.message||'ارسال کد ناموفق بود.'}finally{loading.value=false}}async function verify(){loading.value=true;try{const r=await api<any>('/auth/otp/verify',{method:'POST',body:{mobile:mobile.value,code:code.value,device_name:'store-web'}});token.value=r.token;await navigateTo(String(route.query.redirect||'/'))}catch(e:any){error.value=e?.data?.message||'کد واردشده صحیح نیست.'}finally{loading.value=false}}</script>
<template><div class="mx-auto max-w-md px-4 py-16"><div class="rounded-3xl border bg-white p-7 shadow-soft"><h1 class="text-2xl font-black">ورود یا ثبت‌نام</h1><p class="mt-2 text-sm leading-7 text-slate-500">شماره موبایل شما برای ورود امن و پیگیری سفارش استفاده می‌شود.</p><form class="mt-8 space-y-5" @submit.prevent="step==='mobile'?send():verify()"><label class="block"><span class="mb-2 block text-sm font-bold">شماره موبایل</span><input v-model="mobile" dir="ltr" :disabled="step==='code'" class="h-12 w-full rounded-xl border px-4 text-left outline-none focus:border-brand-700"></label><label v-if="step==='code'" class="block"><span class="mb-2 block text-sm font-bold">کد ورود</span><input v-model="code" dir="ltr" maxlength="5" class="h-12 w-full rounded-xl border px-4 text-center text-xl tracking-[.5em] outline-none focus:border-brand-700"></label><p v-if="error" class="rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{{error}}</p><button :disabled="loading" class="h-12 w-full rounded-xl bg-brand-700 font-black text-white disabled:opacity-50">{{loading?'کمی صبر کنید…':step==='mobile'?'دریافت کد':'ورود به حساب'}}</button></form></div></div></template>
